int atl2_probe(struct pci_dev *pdev, const struct pci_device_id *ent) {
    struct net_device *netdev;
    int err;

    err = pci_enable_device(pdev);
    if (err < 0)
        return err;

    if ((err = pci_set_dma_mask(pdev, DMA_BIT_MASK(32))) &&
        (err = pci_set_dma_mask(pdev, DMA_BIT_MASK(24)))) {
        dev_err(&pdev->dev, "No usable DMA configuration\n");
        goto err_out_disable_pdev;
    }

    if (!request_pci_regions(pdev, "atl2")) {
        err = -EBUSY;
        goto err_out_disable_pdev;
    }

    netdev = alloc_etherdev(sizeof(struct atl2_adapter));
    if (!netdev) {
        err = -ENOMEM;
        goto err_out_release_regions;
    }

    SET_NETDEV_PRIV(netdev, pdev, NULL);
    netdev->irq = pdev->irq;

    netdev->netdev_ops = &atl2_netdev_ops;
    netdev->watchdog_timeo = 5 * HZ;

    setup_timer(&((struct atl2_adapter *)netdev->priv)->watchdog_timer,
                atl2_watchdog, (unsigned long)netdev);

    setup_timer(&((struct atl2_adapter *)netdev->priv)->phy_config_timer,
                atl2_phy_config, (unsigned long)netdev);

    err = register_netdev(netdev);
    if (err)
        goto err_out_free_netdev;

    err = atl2_read_mac_addr(pdev, netdev);
    if (err)
        goto err_out_unregister_netdev;

    atl2_hw_init(pdev);

    return 0;

err_out_unregister_netdev:
    unregister_netdev(netdev);
err_out_free_netdev:
    free_netdev(netdev);
err_out_release_regions:
    release_pci_regions(pdev);
err_out_disable_pdev:
    pci_disable_device(pdev);
    return err;
}

int atl2_probe(struct pci_dev *pdev, const struct pci_device_id *ent) {
    int err;
    struct net_device *netdev;
    struct atl2_adapter *adapter;

    err = pci_enable_device(pdev);
    if (err < 0)
        return err;

    err = pci_set_dma_mask(pdev, DMA_BIT_MASK(32));
    if (err) {
        pci_disable_device(pdev);
        return err;
    }

    err = pci_request_regions(pdev, "atl2");
    if (err) {
        pci_disable_device(pdev);
        return err;
    }

    netdev = alloc_etherdev(sizeof(struct atl2_adapter));
    if (!netdev) {
        pci_release_regions(pdev);
        pci_disable_device(pdev);
        return -ENOMEM;
    }

    adapter = netdev_priv(netdev);
    adapter->pdev = pdev;
    adapter->netdev = netdev;

    pci_set_drvdata(pdev, netdev);

    netdev->irq = pdev->irq;
    netdev->base_addr = pci_resource_start(pdev, 0);
    SET_NETDEV_DEV(netdev, &pdev->dev);

    if (!is_valid_ether_addr(netdev->dev_addr)) {
        err = atl2_get_mac_address(pdev, netdev->dev_addr);
        if (err) {
            free_netdev(netdev);
            pci_release_regions(pdev);
            pci_disable_device(pdev);
            return err;
        }
    }

    err = atl2_setup_hw(adapter);
    if (err) {
        free_netdev(netdev);
        pci_release_regions(pdev);
        pci_disable_device(pdev);
        return err;
    }

    setup_timer(&adapter->watchdog_timer, atl2_watchdog, (unsigned long)adapter);
    setup_timer(&adapter->phy_config_timer, atl2_phy_config, (unsigned long)adapter);

    err = register_netdev(netdev);
    if (err) {
        del_timer_sync(&adapter->watchdog_timer);
        del_timer_sync(&adapter->phy_config_timer);
        atl2_clean_hw(adapter);
        free_netdev(netdev);
        pci_release_regions(pdev);
        pci_disable_device(pdev);
        return err;
    }

    return 0;
}

int atl2_probe(struct pci_dev *pdev, const struct pci_device_id *ent) {
    struct net_device *netdev;
    int err;

    err = pci_enable_device(pdev);
    if (err < 0)
        return err;

    err = pci_set_dma_mask(pdev, DMA_32BIT_MASK);
    if (err < 0)
        goto err_dma_mask;

    err = pci_request_regions(pdev, "atl2");
    if (err < 0)
        goto err_regions;

    netdev = alloc_etherdev(sizeof(struct atl2_adapter));
    if (!netdev) {
        err = -ENOMEM;
        goto err_alloc;
    }

    netdev->irq = pdev->irq;
    pci_set_drvdata(pdev, netdev);
    SET_NETDEV_DEV(netdev, &pdev->dev);

    err = atl2_sw_init(netdev);
    if (err < 0)
        goto err_sw_init;

    err = atl2_hw_init(netdev);
    if (err < 0)
        goto err_hw_init;

    err = register_netdev(netdev);
    if (err < 0)
        goto err_reg_netdev;

    return 0;

err_reg_netdev:
    atl2_reset_hw(netdev);
err_hw_init:
    atl2_sw_free(netdev);
err_sw_init:
    free_netdev(netdev);
err_alloc:
    pci_release_regions(pdev);
err_regions:
    pci_clear_dma_mask(pdev);
err_dma_mask:
    pci_disable_device(pdev);
    return err;
}
